415	      return;
416	    }
417	    const fullPrompt = [
418	      "Design a complete, playable, original tabletop board game prototype.",
419	      templateHint ? `It should be a ${templateHint}.` : "",
420	      prompt ? `User direction: ${prompt}` : "",
421	      "",
422	      "Output ONLY a valid JSON object with this exact shape (no markdown, no commentary):",
423	      `{
424	  "name": "string — short and memorable (max 30 chars)",
425	  "description": "string — 2-3 sentence elevator pitch",
426	  "gameType": "Strategy|Party|Cooperative|Deck-builder|...",
427	  "genre": "Fantasy|Sci-fi|Modern|Historical|Abstract|...",
428	  "playerCount": "e.g. 2-4",
429	  "targetDuration": "e.g. 30-45 minutes",
430	  "complexityScore": 1-10,
431	  "blueprint": "string — 3-5 short paragraphs covering core loop, win condition, turn structure, balance",
432	  "entities": [{ "name": "string", "type": "card|token|board|piece|resource|other", "description": "string (1-2 sentences)" }],
433	  "rules": [{ "title": "string", "category": "Setup|Turn|Action|Scoring|Endgame", "content": "string — 1-3 sentences, clear and actionable" }],
434	  "players": [{ "name": "string — role/archetype name", "role": "string", "description": "string (1-2 sentences)" }],
435	  "notes": [{ "title": "string", "content": "string — short designer note" }]
436	}`,
437	      "",
438	      "Aim for: ~5-7 entities, ~5-7 rules, ~3-4 player roles (only if relevant), ~2 notes.",
439	      "Keep every string concise. Total response must fit comfortably in the JSON. All text must be production-quality and immediately usable.",
440	    ]
441	      .filter(Boolean)
442	      .join("\n");
443	
444	    let raw: string;
445	    try {
446	      raw = await complete(req, {
447	        prompt: fullPrompt,
448	        system:
449	          "You are a world-class senior tabletop game designer. You only output the requested JSON, never any prose, markdown, or commentary. Be concise so the JSON always closes cleanly.",
450	        maxTokens: 8000,
451	        kind: "structured",
452	        preferFast: true,
453	      });
454	    } catch (e) {
455	      const msg = e instanceof Error ? e.message : String(e);
456	      res.status(502).json({ error: `AI generation failed: ${msg}` });
457	      return;
458	    }
459	
460	    const parsed = tryParseJsonObject<{
461	      name?: string;
462	      description?: string;
463	      gameType?: string;
464	      genre?: string;
465	      playerCount?: string;
466	      targetDuration?: string;
467	      complexityScore?: number;
468	      blueprint?: string;
469	      entities?: Array<{ name?: string; type?: string; description?: string }>;
470	      rules?: Array<{ title?: string; category?: string; content?: string }>;
471	      players?: Array<{ name?: string; role?: string; description?: string }>;
472	      notes?: Array<{ title?: string; content?: string }>;
473	    }>(raw);
474	    if (!parsed) {
475	      req.log.warn({ rawPreview: raw.slice(0, 500) }, "workspace generate: AI output unparseable");
476	      res.status(502).json({
477	        error:
478	          "The AI returned an unreadable response. This is usually transient — please try again, or simplify your prompt.",
479	      });
480	      return;
481	    }
482	
483	    // Minimum-viability check: at least one of blueprint/rules/entities must be present,
484	    // otherwise the generated project is too empty to be useful.
485	    const ruleCount = Array.isArray(parsed.rules) ? parsed.rules.length : 0;
486	    const entityCount = Array.isArray(parsed.entities) ? parsed.entities.length : 0;
487	    const hasBlueprint = !!(parsed.blueprint && String(parsed.blueprint).trim().length > 50);
488	    if (!hasBlueprint && ruleCount === 0 && entityCount === 0) {
489	      req.log.warn(
