517	          const slug = await generateProjectSlug(req.workspace!.id, name);
518	          try {
519	            const rows = await tx
520	              .insert(projects)
521	              .values({
522	                workspaceId: req.workspace!.id,
523	                ownerUserId: req.appUserId ?? undefined,
524	                slug,
525	                name,
526	                description: parsed.description ?? null,
527	                gameType: parsed.gameType ?? null,
528	                genre: parsed.genre ?? null,
529	                playerCount: parsed.playerCount ?? null,
530	                targetDuration: parsed.targetDuration ?? null,
531	                complexityScore:
532	                  typeof parsed.complexityScore === "number"
533	                    ? Math.max(1, Math.min(10, Math.round(parsed.complexityScore)))
534	                    : null,
535	                blueprint: parsed.blueprint ?? null,
536	              })
537	              .returning();
538	            inserted = rows[0];
539	          } catch (err) {
540	            if (!isUniqueViolation(err)) throw err;
541	            // raced — loop with a fresh slug
542	          }
543	        }
544	        if (!inserted) throw new Error("Could not allocate project slug");
545	
546	        if (Array.isArray(parsed.entities) && parsed.entities.length) {
547	          await tx.insert(entities).values(
548	            parsed.entities.slice(0, 20).map((e) => ({
549	              projectId: inserted!.id,
550	              name: String(e.name ?? "Entity").slice(0, 80),
551	              type: String(e.type ?? "other").slice(0, 40),
552	              description: e.description ? String(e.description) : null,
553	            })),
554	          );
555	        }
556	        if (Array.isArray(parsed.rules) && parsed.rules.length) {
557	          await tx.insert(rules).values(
558	            parsed.rules.slice(0, 20).map((r) => ({
559	              projectId: inserted!.id,
560	              title: String(r.title ?? "Rule").slice(0, 100),
561	              category: r.category ? String(r.category).slice(0, 40) : null,
562	              content: String(r.content ?? ""),
563	            })),
564	          );
565	        }
