567	          await tx.insert(players).values(
568	            parsed.players.slice(0, 12).map((p) => ({
569	              projectId: inserted!.id,
570	              name: String(p.name ?? "Role").slice(0, 80),
571	              role: p.role ? String(p.role).slice(0, 80) : null,
572	              description: p.description ? String(p.description) : null,
573	            })),
574	          );
575	        }
576	        if (Array.isArray(parsed.notes) && parsed.notes.length) {
577	          await tx.insert(notes).values(
578	            parsed.notes.slice(0, 8).map((n) => ({
579	              projectId: inserted!.id,
580	              title: n.title ? String(n.title).slice(0, 100) : "Designer note",
581	              content: n.content ? String(n.content) : null,
582	            })),
583	          );
584	        }
